**React with hooks:**
```javascript
import { useState, useRef, useCallback } from 'react';

export function SearchInput() {
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  const handleSearch = useCallback((value) => {
    // Clear previous timeout
    clearTimeout(timeoutRef.current);

    // Set new timeout
    timeoutRef.current = setTimeout(async () => {
      const res = await fetch(`/api/search?q=${encodeURIComponent(value)}`);
      const data = await res.json();
      setResults(data);
    }, 300); // 300ms delay
  }, []);

  return (
    <>
      <input
        type="text"
        placeholder="Search..."
        onChange={(e) => handleSearch(e.target.value)}
      />
      <ul>
        {results.map(item => <li key={item.id}>{item.name}</li>)}
      </ul>
    </>
  );
}
```

**Or use a reusable debounce hook:**
```javascript
function useDebounce(callback, delay) {
  const timeoutRef = useRef(null);

  return useCallback((...args) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => callback(...args), delay);
  }, [callback, delay]);
}

// Usage:
const debouncedSearch = useDebounce(async (value) => {
  const res = await fetch(`/api/search?q=${encodeURIComponent(value)}`);
  setResults(await res.json());
}, 300);

<input onChange={(e) => debouncedSearch(e.target.value)} />
```

**Vanilla JS:**
```javascript
let timeoutId;
const input = document.getElementById('search');

input.addEventListener('input', (e) => {
  clearTimeout(timeoutId);
  timeoutId = setTimeout(async () => {
    const res = await fetch(`/api/search?q=${encodeURIComponent(e.target.value)}`);
    const results = await res.json();
    // Update UI with results
  }, 300);
});
```

The key principle: clear the previous timeout before setting a new one, so the API call only fires after 300ms of inactivity. Adjust the delay based on your needs (200-500ms is typical). Which approach fits your setup?
